INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('e2iofr7sng','published','2026-03-21T18:14:20.504Z','2026-03-21T18:14:20.504Z','{"title":"A Sunday Feast at Vínstúkan","slug":"sunday-feast-vinstukan","excerpt":"Oysters, duck à l''orange, wines flowing — a family-style Sunday lunch at Vínstúkan that was one of my highlights from December.","date":"2026-01-24T00:00:00.000Z","image":"qn65k1j3on","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"This Sunday lunch at Vínstúkan was one of my highlights from December."}]},{"type":"block","item":"p0uc2wavt5"},{"type":"block","item":"2yjlfsixof"},{"type":"block","item":"rn1aittsf2"},{"type":"block","item":"wp9jyeb0i2"},{"type":"paragraph","children":[{"type":"span","value":"Oysters, pâté de campagne, fresh salad with anchovies, whole roasted duck à l''orange, potatoes cooked in duck fat, mushrooms, and a trifle to finish — all served family-style, with wines flowing and perfectly paired throughout."}]},{"type":"paragraph","children":[{"type":"span","value":"The food was honestly so good, but the company was even better. Long tables, shared plates, zero rush, lots of laughter. This is exactly how meals should be."}]},{"type":"paragraph","children":[{"type":"span","value":"They haven''t announced the next one yet, but they have to do this again. If and when they do: don''t miss it. I definitely won''t."}]},{"type":"paragraph","children":[{"type":"span","value":"Big thanks to Óli and Steinarr for hosting something this lovely."}]}]}},"blocks":{"p0uc2wavt5":{"_type":"image_block","image":"qeqmnl06wm","caption":"A Sunday Feast at Vínstúkan - photo 2"},"2yjlfsixof":{"_type":"image_block","image":"wr7lddhzp5","caption":"A Sunday Feast at Vínstúkan - photo 3"},"rn1aittsf2":{"_type":"image_block","image":"cf50fo3o5i","caption":"A Sunday Feast at Vínstúkan - photo 4"},"wp9jyeb0i2":{"_type":"image_block","image":"rco8btu3dl","caption":"A Sunday Feast at Vínstúkan - photo 5"}}}}','2026-03-21T18:14:19.689Z','2026-03-21T18:14:20.504Z','admin','admin','admin',NULL,NULL,'A Sunday Feast at Vínstúkan','sunday-feast-vinstukan','Oysters, duck à l''orange, wines flowing — a family-style Sunday lunch at Vínstúkan that was one of my highlights from December.','2026-01-24T00:00:00.000Z','qn65k1j3on','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"This Sunday lunch at Vínstúkan was one of my highlights from December."}]},{"type":"block","item":"p0uc2wavt5"},{"type":"block","item":"2yjlfsixof"},{"type":"block","item":"rn1aittsf2"},{"type":"block","item":"wp9jyeb0i2"},{"type":"paragraph","children":[{"type":"span","value":"Oysters, pâté de campagne, fresh salad with anchovies, whole roasted duck à l''orange, potatoes cooked in duck fat, mushrooms, and a trifle to finish — all served family-style, with wines flowing and perfectly paired throughout."}]},{"type":"paragraph","children":[{"type":"span","value":"The food was honestly so good, but the company was even better. Long tables, shared plates, zero rush, lots of laughter. This is exactly how meals should be."}]},{"type":"paragraph","children":[{"type":"span","value":"They haven''t announced the next one yet, but they have to do this again. If and when they do: don''t miss it. I definitely won''t."}]},{"type":"paragraph","children":[{"type":"span","value":"Big thanks to Óli and Steinarr for hosting something this lovely."}]}]}}');
INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('sv8gdgoaxg','published','2026-03-21T18:14:21.602Z','2026-03-21T18:14:21.602Z','{"title":"End of an Era: Farewell to Slippurinn","slug":"farewell-slippurinn","excerpt":"My last meal at Slippurinn in the Westman Islands. They''ve closed their doors for good, but what they leave behind is a legacy.","date":"2025-11-08T00:00:00.000Z","image":"tarhq6jnd6","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"End of an era. These photos are from my last meal at Slippurinn in the Westman Islands this summer. They have now closed their doors for good, but what they leave behind is a legacy of memories and inspiration for the entire food community in Iceland."}]},{"type":"block","item":"96vkjwlly3"},{"type":"block","item":"i546ly4cyc"},{"type":"block","item":"brdenmchei"},{"type":"block","item":"1olgeieqja"},{"type":"block","item":"nlwzikjtyw"},{"type":"paragraph","children":[{"type":"span","value":"Even though it''s sad to say goodbye, it''s also brave to end on a high note — moving on to new projects while leaving behind something truly great. This meal was one of the most memorable I''ve ever had, from start to finish. Gísli Matt, owner and chef, was there serving us himself and making us feel both special and at home."}]},{"type":"paragraph","children":[{"type":"span","value":"We even had our kids with us, and they loved trying the wildest, most creative dishes — all locally sourced from the island. I honestly can''t even pick a highlight because it was all so good."}]},{"type":"paragraph","children":[{"type":"span","value":"Thank you, Gísli, and thank you, Slippurinn, for giving us a memory of a lifetime."}]}]}},"blocks":{"96vkjwlly3":{"_type":"image_block","image":"22dkfu8ylu","caption":"End of an Era: Farewell to Slippurinn - photo 2"},"i546ly4cyc":{"_type":"image_block","image":"fbzv5minyn","caption":"End of an Era: Farewell to Slippurinn - photo 3"},"brdenmchei":{"_type":"image_block","image":"y7dmav3hoy","caption":"End of an Era: Farewell to Slippurinn - photo 4"},"1olgeieqja":{"_type":"image_block","image":"yktty8p6qn","caption":"End of an Era: Farewell to Slippurinn - photo 5"},"nlwzikjtyw":{"_type":"image_block","image":"hp6m1jspxw","caption":"End of an Era: Farewell to Slippurinn - photo 6"}}}}','2026-03-21T18:14:20.650Z','2026-03-21T18:14:21.602Z','admin','admin','admin',NULL,NULL,'End of an Era: Farewell to Slippurinn','farewell-slippurinn','My last meal at Slippurinn in the Westman Islands. They''ve closed their doors for good, but what they leave behind is a legacy.','2025-11-08T00:00:00.000Z','tarhq6jnd6','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"End of an era. These photos are from my last meal at Slippurinn in the Westman Islands this summer. They have now closed their doors for good, but what they leave behind is a legacy of memories and inspiration for the entire food community in Iceland."}]},{"type":"block","item":"96vkjwlly3"},{"type":"block","item":"i546ly4cyc"},{"type":"block","item":"brdenmchei"},{"type":"block","item":"1olgeieqja"},{"type":"block","item":"nlwzikjtyw"},{"type":"paragraph","children":[{"type":"span","value":"Even though it''s sad to say goodbye, it''s also brave to end on a high note — moving on to new projects while leaving behind something truly great. This meal was one of the most memorable I''ve ever had, from start to finish. Gísli Matt, owner and chef, was there serving us himself and making us feel both special and at home."}]},{"type":"paragraph","children":[{"type":"span","value":"We even had our kids with us, and they loved trying the wildest, most creative dishes — all locally sourced from the island. I honestly can''t even pick a highlight because it was all so good."}]},{"type":"paragraph","children":[{"type":"span","value":"Thank you, Gísli, and thank you, Slippurinn, for giving us a memory of a lifetime."}]}]}}');
INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('m8i0be9ps9','published','2026-03-21T18:14:22.622Z','2026-03-21T18:14:22.622Z','{"title":"A Day Trip to Næs in the Westman Islands","slug":"day-trip-naes-westman-islands","excerpt":"Took the fam on a day trip to the Westman Islands. First stop was Næs, the tiny sister restaurant to the iconic Slippurinn that has since closed their doors.","date":"2025-07-25T00:00:00.000Z","image":"7k0789801q","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Took the fam on a day trip to the Westman Islands — this is Part 1 of 2!"}]},{"type":"paragraph","children":[{"type":"span","value":"First stop was Næs, the tiny sister restaurant to the iconic Slippurinn. Small place but big vibes — the interior, the look and feel, everything was just so nice. (And yep, Næs literally means “Nice” — just with the Icelandic letters.)"}]},{"type":"block","item":"bbvf08xo6j"},{"type":"block","item":"3ruvp0vp7p"},{"type":"block","item":"pliv3dmtru"},{"type":"block","item":"lqfrq7c312"},{"type":"block","item":"8993galv9o"},{"type":"paragraph","children":[{"type":"span","value":"We were greeted with such warm, friendly service — even with the kids there, nothing was a hassle. Gísli Matt was even there to welcome us. Just an all-around amazing experience you shouldn''t miss if you''re ever in Eyjar."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The food"}]},{"type":"paragraph","children":[{"type":"span","value":"We started with the grilled flatbread with roasted pepper and hazelnut crema — absolute flavour bomb, I had to stop myself from licking the bowl. And the sweet tomatoes with stracciatella and basil, which we scooped up in no time."}]},{"type":"paragraph","children":[{"type":"span","value":"As a little extra treat, they brought out a small toasted sourdough slice topped with Icelandic lamb nduja: spicy, sweet, total umami hit. So good."}]},{"type":"paragraph","children":[{"type":"span","value":"For mains I had the fresh catch of the day with potato purée, brown butter and capers. The fish was perfectly cooked, flaky and tender. And the hubby had the lamb with chimichurri and a side of grilled veggies — also incredible."}]},{"type":"paragraph","children":[{"type":"span","value":"For dessert: sky mousse with rhubarb and oat crumble. Light, tangy, and the perfect ending."}]},{"type":"paragraph","children":[{"type":"span","value":"If you''re planning a trip to the Westman Islands, Næs is a must.","marks":["strong"]}]}]}},"blocks":{"bbvf08xo6j":{"_type":"image_block","image":"muavdb07bl","caption":"A Day Trip to Næs in the Westman Islands - photo 2"},"3ruvp0vp7p":{"_type":"image_block","image":"qzf5pos5da","caption":"A Day Trip to Næs in the Westman Islands - photo 3"},"pliv3dmtru":{"_type":"image_block","image":"pfg74g09eg","caption":"A Day Trip to Næs in the Westman Islands - photo 4"},"lqfrq7c312":{"_type":"image_block","image":"q43l79upih","caption":"A Day Trip to Næs in the Westman Islands - photo 5"},"8993galv9o":{"_type":"image_block","image":"zisc84g3hv","caption":"A Day Trip to Næs in the Westman Islands - photo 6"}}}}','2026-03-21T18:14:21.740Z','2026-03-21T18:14:22.622Z','admin','admin','admin',NULL,NULL,'A Day Trip to Næs in the Westman Islands','day-trip-naes-westman-islands','Took the fam on a day trip to the Westman Islands. First stop was Næs, the tiny sister restaurant to the iconic Slippurinn that has since closed their doors.','2025-07-25T00:00:00.000Z','7k0789801q','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Took the fam on a day trip to the Westman Islands — this is Part 1 of 2!"}]},{"type":"paragraph","children":[{"type":"span","value":"First stop was Næs, the tiny sister restaurant to the iconic Slippurinn. Small place but big vibes — the interior, the look and feel, everything was just so nice. (And yep, Næs literally means “Nice” — just with the Icelandic letters.)"}]},{"type":"block","item":"bbvf08xo6j"},{"type":"block","item":"3ruvp0vp7p"},{"type":"block","item":"pliv3dmtru"},{"type":"block","item":"lqfrq7c312"},{"type":"block","item":"8993galv9o"},{"type":"paragraph","children":[{"type":"span","value":"We were greeted with such warm, friendly service — even with the kids there, nothing was a hassle. Gísli Matt was even there to welcome us. Just an all-around amazing experience you shouldn''t miss if you''re ever in Eyjar."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The food"}]},{"type":"paragraph","children":[{"type":"span","value":"We started with the grilled flatbread with roasted pepper and hazelnut crema — absolute flavour bomb, I had to stop myself from licking the bowl. And the sweet tomatoes with stracciatella and basil, which we scooped up in no time."}]},{"type":"paragraph","children":[{"type":"span","value":"As a little extra treat, they brought out a small toasted sourdough slice topped with Icelandic lamb nduja: spicy, sweet, total umami hit. So good."}]},{"type":"paragraph","children":[{"type":"span","value":"For mains I had the fresh catch of the day with potato purée, brown butter and capers. The fish was perfectly cooked, flaky and tender. And the hubby had the lamb with chimichurri and a side of grilled veggies — also incredible."}]},{"type":"paragraph","children":[{"type":"span","value":"For dessert: sky mousse with rhubarb and oat crumble. Light, tangy, and the perfect ending."}]},{"type":"paragraph","children":[{"type":"span","value":"If you''re planning a trip to the Westman Islands, Næs is a must.","marks":["strong"]}]}]}}');
INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('zxhx8uuoaw','published','2026-03-21T18:14:23.620Z','2026-03-21T18:14:23.620Z','{"title":"Austur-Indíafélagið Turns 30","slug":"austur-india-turns-30","excerpt":"A night of pure magic at Austur-Indíafélagið''s 30th birthday celebration. 30 dishes tracing three decades of unforgettable flavours.","date":"2025-05-16T00:00:00.000Z","image":"fnq0rvhugr","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Throwing it back to a night of pure magic at Austur-Indíafjelagið''s 30th birthday celebration — yes, this post is fashionably late, but some evenings are too good not to revisit."}]},{"type":"block","item":"x8eeji4mra"},{"type":"block","item":"9dtq8n3vhs"},{"type":"block","item":"jf8inpch51"},{"type":"block","item":"e16nnx8bzn"},{"type":"block","item":"8etpgguekc"},{"type":"paragraph","children":[{"type":"span","value":"Austur-Indía has been a pillar of Reykjavík''s dining scene since 1994, masterfully blending Icelandic ingredients with Indian spice and soul. For the anniversary, they served up 30 dishes that traced their journey through three decades of unforgettable flavours."}]},{"type":"paragraph","children":[{"type":"span","value":"At the heart of it all is Chandrika Gunnarsson — a true inspiration whose vision brought Indian cuisine to Iceland and helped shape the city''s culinary identity."}]},{"type":"paragraph","children":[{"type":"span","value":"An evening full of spice, warmth, and celebration — shared with some amazing foodie friends."}]}]}},"blocks":{"x8eeji4mra":{"_type":"image_block","image":"cg05q1z2q9","caption":"Austur-Indíafélagið Turns 30 - photo 2"},"9dtq8n3vhs":{"_type":"image_block","image":"87ijmrme1v","caption":"Austur-Indíafélagið Turns 30 - photo 3"},"jf8inpch51":{"_type":"image_block","image":"dituxwytz7","caption":"Austur-Indíafélagið Turns 30 - photo 4"},"e16nnx8bzn":{"_type":"image_block","image":"8hnrrqgvkl","caption":"Austur-Indíafélagið Turns 30 - photo 5"},"8etpgguekc":{"_type":"image_block","image":"3r9ee4yhh0","caption":"Austur-Indíafélagið Turns 30 - photo 6"}}}}','2026-03-21T18:14:22.768Z','2026-03-21T18:14:23.620Z','admin','admin','admin',NULL,NULL,'Austur-Indíafélagið Turns 30','austur-india-turns-30','A night of pure magic at Austur-Indíafélagið''s 30th birthday celebration. 30 dishes tracing three decades of unforgettable flavours.','2025-05-16T00:00:00.000Z','fnq0rvhugr','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Throwing it back to a night of pure magic at Austur-Indíafjelagið''s 30th birthday celebration — yes, this post is fashionably late, but some evenings are too good not to revisit."}]},{"type":"block","item":"x8eeji4mra"},{"type":"block","item":"9dtq8n3vhs"},{"type":"block","item":"jf8inpch51"},{"type":"block","item":"e16nnx8bzn"},{"type":"block","item":"8etpgguekc"},{"type":"paragraph","children":[{"type":"span","value":"Austur-Indía has been a pillar of Reykjavík''s dining scene since 1994, masterfully blending Icelandic ingredients with Indian spice and soul. For the anniversary, they served up 30 dishes that traced their journey through three decades of unforgettable flavours."}]},{"type":"paragraph","children":[{"type":"span","value":"At the heart of it all is Chandrika Gunnarsson — a true inspiration whose vision brought Indian cuisine to Iceland and helped shape the city''s culinary identity."}]},{"type":"paragraph","children":[{"type":"span","value":"An evening full of spice, warmth, and celebration — shared with some amazing foodie friends."}]}]}}');
INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('uyjk9adkii','published','2026-03-23T19:59:21.528Z','2026-03-21T18:14:24.613Z','{"title":"Why We Love Skreið","slug":"why-we-love-skreid","excerpt":"A Basque-inspired tapas bar in a charming black house on Laugavegur. Great wine, great vibes, and one of our favorite spots in Reykjavík.","date":"2025-02-17T00:00:00.000Z","image":"p66iptw5yn","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Skreið is a Basque-inspired tapas restaurant and bar tucked into a charming black house at Laugavegur 4. It was opened a couple of years ago by friends Steinþór and Davíð Örn, and the inspiration comes straight from their travels through the Basque Country."}]},{"type":"paragraph","children":[{"type":"span","value":"The vibe is laid-back but polished — cool staff, good music, the kind of place that works equally well for a casual drink or a proper date night. The interior has that effortless Scandinavian-meets-Southern-European feel that just makes you want to stay longer than you planned."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The wine"}]},{"type":"paragraph","children":[{"type":"span","value":"For a small place, Skreið has an impressively deep wine list. The focus is on Spanish wines, which makes sense given the Basque influence, but they also keep things interesting with bottles from other regions. The staff actually knows the list and can guide you to something great based on what you''re eating."}]},{"type":"block","item":"32bei45v3n"},{"type":"heading","level":2,"children":[{"type":"span","value":"The food"}]},{"type":"paragraph","children":[{"type":"span","value":"Think tapas with Icelandic ingredients. Small plates made for sharing, bold flavours, and everything comes out looking beautiful. It''s the kind of menu where you order too much and don''t regret it."}]},{"type":"block","item":"img7648"},{"type":"block","item":"img7651"},{"type":"block","item":"img7654"},{"type":"block","item":"img7660"},{"type":"paragraph","children":[{"type":"span","value":"We recommend Skreið for anyone who loves tapas and good vibes.","marks":["strong"]},{"type":"span","value":" It''s in our "},{"type":"span","value":"Reykjavík Food Guide","marks":["strong"]},{"type":"span","value":" for a reason — this is a perfect date night spot."}]}]}},"blocks":{"32bei45v3n":{"_type":"image_block","image":"udl7z0hejy","caption":"Wine bottle candle at Skreið"},"img7648":{"_type":"image_block","image":"45e53487-8809-46a3-bb9b-3894da3ac924","caption":""},"img7651":{"_type":"image_block","image":"1bc08be4-986e-4ff7-99ac-7b71483cb4a5","caption":""},"img7654":{"_type":"image_block","image":"8341a559-8027-45b0-b58f-404f8d37aa94","caption":""},"img7660":{"_type":"image_block","image":"249fa0a6-531d-4aa3-b0eb-6334afd841f7","caption":""}}}}','2026-03-21T18:14:23.773Z','2026-03-23T19:59:21.528Z','admin','Sunna','Sunna',NULL,NULL,'Why We Love Skreið','why-we-love-skreid','A Basque-inspired tapas bar in a charming black house on Laugavegur. Great wine, great vibes, and one of our favorite spots in Reykjavík.','2025-02-17T00:00:00.000Z','p66iptw5yn','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Skreið is a Basque-inspired tapas restaurant and bar tucked into a charming black house at Laugavegur 4. It was opened a couple of years ago by friends Steinþór and Davíð Örn, and the inspiration comes straight from their travels through the Basque Country."}]},{"type":"paragraph","children":[{"type":"span","value":"The vibe is laid-back but polished — cool staff, good music, the kind of place that works equally well for a casual drink or a proper date night. The interior has that effortless Scandinavian-meets-Southern-European feel that just makes you want to stay longer than you planned."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The wine"}]},{"type":"paragraph","children":[{"type":"span","value":"For a small place, Skreið has an impressively deep wine list. The focus is on Spanish wines, which makes sense given the Basque influence, but they also keep things interesting with bottles from other regions. The staff actually knows the list and can guide you to something great based on what you''re eating."}]},{"type":"block","item":"32bei45v3n"},{"type":"heading","level":2,"children":[{"type":"span","value":"The food"}]},{"type":"paragraph","children":[{"type":"span","value":"Think tapas with Icelandic ingredients. Small plates made for sharing, bold flavours, and everything comes out looking beautiful. It''s the kind of menu where you order too much and don''t regret it."}]},{"type":"block","item":"img7648"},{"type":"block","item":"img7651"},{"type":"block","item":"img7654"},{"type":"block","item":"img7660"},{"type":"paragraph","children":[{"type":"span","value":"We recommend Skreið for anyone who loves tapas and good vibes.","marks":["strong"]},{"type":"span","value":" It''s in our "},{"type":"span","value":"Reykjavík Food Guide","marks":["strong"]},{"type":"span","value":" for a reason — this is a perfect date night spot."}]}]}}');
INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('o5oalpl1oq','published','2026-03-21T18:14:25.696Z','2026-03-21T18:14:25.696Z','{"title":"Coocoo''s Nest Is Back — at Harpa","slug":"coocoos-nest-is-back-harpa","excerpt":"Reykjavík''s iconic brunch is back, thanks to Lucas Keller and Leifur at La Primavera — every weekend this winter at Hnoss Bistro in Harpa.","date":"2024-09-26T00:00:00.000Z","image":"sd87pbaiwg","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Honey, wake up — huge news in the Icelandic food scene just dropped!"}]},{"type":"block","item":"951qpfzw58"},{"type":"block","item":"t8n4j30ai4"},{"type":"block","item":"ppe6mbpypq"},{"type":"block","item":"813ngjr04d"},{"type":"paragraph","children":[{"type":"span","value":"If you''re anything like me, you think about those egg Florentine sourdough bites every time you''re even slightly hungover. Those sinful brownies, triple shot hangover ice lattes, breakfast burritos, and pesto eggs…"}]},{"type":"paragraph","children":[{"type":"span","value":"Well, toss out that Coocoo''s Nest eulogy because Reykjavík''s iconic brunch is back, thanks to Lucas Keller and Leifur at La Primavera — every weekend this winter at Hnoss Bistro in Harpa."}]}]}},"blocks":{"951qpfzw58":{"_type":"image_block","image":"ld2ffjb0us","caption":"Coocoo''s Nest Is Back — at Harpa - photo 2"},"t8n4j30ai4":{"_type":"image_block","image":"kcsk288gxy","caption":"Coocoo''s Nest Is Back — at Harpa - photo 3"},"ppe6mbpypq":{"_type":"image_block","image":"nj8k70j64j","caption":"Coocoo''s Nest Is Back — at Harpa - photo 4"},"813ngjr04d":{"_type":"image_block","image":"sd87pbaiwg","caption":"Coocoo''s Nest Is Back — at Harpa - photo 5"}}}}','2026-03-21T18:14:24.783Z','2026-03-21T18:14:25.696Z','admin','admin','admin',NULL,NULL,'Coocoo''s Nest Is Back — at Harpa','coocoos-nest-is-back-harpa','Reykjavík''s iconic brunch is back, thanks to Lucas Keller and Leifur at La Primavera — every weekend this winter at Hnoss Bistro in Harpa.','2024-09-26T00:00:00.000Z','sd87pbaiwg','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Honey, wake up — huge news in the Icelandic food scene just dropped!"}]},{"type":"block","item":"951qpfzw58"},{"type":"block","item":"t8n4j30ai4"},{"type":"block","item":"ppe6mbpypq"},{"type":"block","item":"813ngjr04d"},{"type":"paragraph","children":[{"type":"span","value":"If you''re anything like me, you think about those egg Florentine sourdough bites every time you''re even slightly hungover. Those sinful brownies, triple shot hangover ice lattes, breakfast burritos, and pesto eggs…"}]},{"type":"paragraph","children":[{"type":"span","value":"Well, toss out that Coocoo''s Nest eulogy because Reykjavík''s iconic brunch is back, thanks to Lucas Keller and Leifur at La Primavera — every weekend this winter at Hnoss Bistro in Harpa."}]}]}}');
INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('0smz99grdv','published','2026-03-21T18:14:26.941Z','2026-03-21T18:14:26.941Z','{"title":"Skál! Gets Its Own Space","slug":"skal-gets-its-own-space-rvk","excerpt":"Skál has moved from Hlemmur Mathöll to its own spot on Njálsgata. Better vibe, better control, same incredible food. It''s like Skál in 4K.","date":"2024-09-20T00:00:00.000Z","image":"5ihgt0gtwt","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"I’ve been a loyal customer of Skál since day one at Hlemmur Mathöll, and now they’ve decided to relocate to their own joint on Njálsgata 1. This has really helped bring out the Skál experience — better control over the vibe, the music, the service, and the interior. It’s like Skál in 4K ultra HD."}]},{"type":"block","item":"jlvj496dr1"},{"type":"block","item":"afa4jhkd9h"},{"type":"block","item":"t9x5xwfzei"},{"type":"block","item":"nfxghh4aa7"},{"type":"heading","level":2,"children":[{"type":"span","value":"The food"}]},{"type":"paragraph","children":[{"type":"span","value":"The focus at Skál is on Icelandic ingredients, treated with creativity and respect. New-Nordic but never pretentious — just fun, flavourful, and beautifully plated. The menu is much the same as before with some thoughtful updates and tweaks. If the cod wings are on, don’t skip them."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The wine"}]},{"type":"paragraph","children":[{"type":"span","value":"The wine list is well curated — interesting bottles, not just the usual suspects. And Reykjavík’s top bartender works here, so the cocktails are worth exploring too."}]},{"type":"paragraph","children":[{"type":"span","value":"Tip: get a seat at the bar for the ultimate Skál experience.","marks":["strong"]},{"type":"span","value":" The service is always a 10, no matter where you sit."}]},{"type":"paragraph","children":[{"type":"span","value":"Congratulations to the whole team on the new space. Skál is in our "},{"type":"span","value":"Reykjavík Food Guide","marks":["strong"]},{"type":"span","value":" — and for good reason."}]}]}},"blocks":{"jlvj496dr1":{"_type":"image_block","image":"fjmf669kz7","caption":"Skál! Gets Its Own Space - photo 2"},"afa4jhkd9h":{"_type":"image_block","image":"go03l55o1k","caption":"Skál! Gets Its Own Space - photo 3"},"t9x5xwfzei":{"_type":"image_block","image":"g43phu1ehe","caption":"Skál! Gets Its Own Space - photo 4"},"nfxghh4aa7":{"_type":"image_block","image":"mpz1lzlili","caption":"Skál! Gets Its Own Space - photo 5"}}}}','2026-03-21T18:14:25.862Z','2026-03-21T18:14:26.941Z','admin','admin','admin',NULL,NULL,'Skál! Gets Its Own Space','skal-gets-its-own-space-rvk','Skál has moved from Hlemmur Mathöll to its own spot on Njálsgata. Better vibe, better control, same incredible food. It''s like Skál in 4K.','2024-09-20T00:00:00.000Z','5ihgt0gtwt','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"I’ve been a loyal customer of Skál since day one at Hlemmur Mathöll, and now they’ve decided to relocate to their own joint on Njálsgata 1. This has really helped bring out the Skál experience — better control over the vibe, the music, the service, and the interior. It’s like Skál in 4K ultra HD."}]},{"type":"block","item":"jlvj496dr1"},{"type":"block","item":"afa4jhkd9h"},{"type":"block","item":"t9x5xwfzei"},{"type":"block","item":"nfxghh4aa7"},{"type":"heading","level":2,"children":[{"type":"span","value":"The food"}]},{"type":"paragraph","children":[{"type":"span","value":"The focus at Skál is on Icelandic ingredients, treated with creativity and respect. New-Nordic but never pretentious — just fun, flavourful, and beautifully plated. The menu is much the same as before with some thoughtful updates and tweaks. If the cod wings are on, don’t skip them."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The wine"}]},{"type":"paragraph","children":[{"type":"span","value":"The wine list is well curated — interesting bottles, not just the usual suspects. And Reykjavík’s top bartender works here, so the cocktails are worth exploring too."}]},{"type":"paragraph","children":[{"type":"span","value":"Tip: get a seat at the bar for the ultimate Skál experience.","marks":["strong"]},{"type":"span","value":" The service is always a 10, no matter where you sit."}]},{"type":"paragraph","children":[{"type":"span","value":"Congratulations to the whole team on the new space. Skál is in our "},{"type":"span","value":"Reykjavík Food Guide","marks":["strong"]},{"type":"span","value":" — and for good reason."}]}]}}');
INSERT INTO "content_editorial" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","excerpt","date","image","content") VALUES('fyuw66y28x','published','2026-03-24T16:57:47.826Z','2026-03-23T17:10:59.148Z','{"title":"Jómfrúin: The Maiden of Lækjargata","slug":"jomfruin","excerpt":"How an Icelandic man trained under Copenhagen''s smørrebrød royalty and brought the craft to Reykjavík — where it''s been a Saturday afternoon institution for nearly thirty years.","date":"2026-03-23","image":"1zb4ixb1xa","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Every Saturday afternoon from June through August, a back garden on Lækjargata fills with the sound of live jazz. People sit in the sun with plates of open-faced sandwiches and cold Icelandic beer. This is Jómfrúin — and it''s been doing this since 1996."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"From Copenhagen to Lækjargata"}]},{"type":"paragraph","children":[{"type":"span","value":"The story starts in 1888, at Oscar Davidsen''s legendary smørrebrød restaurant in Copenhagen — a place so famous its menu was once listed in the Guinness Book of Records as the longest in the world. Generations later, Ida Davidsen inherited the restaurant and continued the tradition."}]},{"type":"paragraph","children":[{"type":"span","value":"In the early 1990s, an Icelandic restaurateur named Jakob Jakobsson trained under Ida Davidsen — becoming the first man in the world to graduate as a "},{"type":"span","value":"smørrebrødsjomfru","marks":["emphasis"]},{"type":"span","value":", the traditional title for a master of open-faced sandwich preparation. The word translates roughly to \"smørrebrød maiden,\" and it had always been held by women. Jakob broke the mould."}]},{"type":"paragraph","children":[{"type":"span","value":"He brought the craft back to Reykjavík and opened Jómfrúin — \"The Maiden\" — on Lækjargata in 1996. The restaurant sits right in the heart of downtown, a few steps from the parliament building and Tjörnin pond."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"What you''re eating"}]},{"type":"paragraph","children":[{"type":"span","value":"Smørrebrød is deceptively simple: a single slice of dark rye bread, buttered, and then piled with toppings arranged with care. At Jómfrúin the classics are all here — pickled herring with onion, smoked salmon with capers, roast beef with remoulade and crispy onions, and the famous "},{"type":"span","value":"rækjupíramídi","marks":["emphasis"]},{"type":"span","value":" (shrimp pyramid!): a towering pyramid of shrimp on a sliver of bread that has become one of the most photographed dishes in Reykjavík."}]},{"type":"block","item":"img_frikadeller"},{"type":"paragraph","children":[{"type":"span","value":"The sandwiches are priced whole or half — and that''s the key to eating here well. You don''t commit to one enormous sandwich. You pick two halves, mix and match, and build your own lunch. The menu of the day always has pairing suggestions if you''re short on ideas, but here are ours: HC Andersen, Danish Adventure, Roast Beef Modern, Smoked Salmon, and Shrimp & Egg. Two halves, one plate, no regrets."}]},{"type":"paragraph","children":[{"type":"span","value":"Beyond the sandwiches, the warm dishes hold their own. "},{"type":"span","value":"Biksemad","marks":["emphasis"]},{"type":"span","value":" — a hash of diced meat and potatoes topped with a fried egg and pickled beets — is comfort food of the highest order."}]},{"type":"paragraph","children":[{"type":"span","value":"The Reykjavík Grapevine''s 2015 Best of Reykjavík panel described the "},{"type":"span","value":"rækjupíramídi","marks":["emphasis"]},{"type":"span","value":" as an \"honest-to-god pyramid of shrimp,\" and called out the \"Hangover\" — roast beef on rye with tomatoes, horseradish, and a fried egg — as a must-order."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"Ákavíti if you''re feeling cheeky"}]},{"type":"block","item":"img_akaviti"},{"type":"paragraph","children":[{"type":"span","value":"The fridge behind the bar is stocked with schnapps — ákavíti in Icelandic — and if you''re having the herring or the shrimp, a small cold glass alongside pairs nicely. It''s a tradition borrowed directly from Denmark, and Jómfrúin takes it seriously."}]},{"type":"block","item":"img_drinks"},{"type":"heading","level":2,"children":[{"type":"span","value":"The Saturday jazz"}]},{"type":"paragraph","children":[{"type":"span","value":"Since its opening year, Jómfrúin has hosted live jazz every Saturday afternoon in summer. Sigurður Flosason, one of Iceland''s most respected jazz musicians, curates the programme. The concerts run from 3 PM to 5 PM, admission is free, and they take place on Jómfrúartorg — the small square behind the restaurant. Check "},{"type":"link","url":"https://jomfruin.is/summar-jazz/","children":[{"type":"span","value":"jomfruin.is/summar-jazz"}]},{"type":"span","value":" for the schedule."}]},{"type":"paragraph","children":[{"type":"span","value":"What started as a casual summer tradition has become one of Reykjavík''s most beloved cultural rituals. The series has grown so popular it won the Icelandic Music Awards for Best Event. Arrive early if you want a seat — by 3 PM on a sunny Saturday, the garden is packed."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"Christmas at Jómfrúin"}]},{"type":"block","item":"img_christmas"},{"type":"paragraph","children":[{"type":"span","value":"Christmas is when Jómfrúin transforms. Families — sometimes groups of twenty or more — book the long tables months in advance. The platters come out piled high: mixed smørrebrød, warm dishes, beer, and schnapps. It has become a Reykjavík tradition for many families to gather here in December, and the restaurant books up fast. If you''re planning a Christmas lunch, call early."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"Still a family affair"}]},{"type":"paragraph","children":[{"type":"span","value":"Jakob''s son, Jakob Jr., took over as manager in 2015, having worked alongside his father since 2003. The handover was seamless — the same recipes, the same standards, the same unhurried pace. Walking into Jómfrúin today feels, as the Grapevine once put it, like being \"transported to 1985 Reykjavík.\" The wood-panelled interior hasn''t changed much. Neither has the quality."}]},{"type":"paragraph","children":[{"type":"span","value":"In a city where restaurants open and close with the seasons, Jómfrúin has been a constant for nearly thirty years. It''s the kind of place where the staff know the regulars, where the portions haven''t shrunk, and where nobody''s trying to reinvent anything. The smørrebrød is the same as it was when Jakob Sr. first laid rye bread on a board here — and that''s exactly the point."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The details"}]},{"type":"paragraph","children":[{"type":"span","value":"Jómfrúin is open daily for lunch and dinner. Reservations aren''t strictly necessary for weekday lunch, but weekend afternoons — especially during jazz season — fill up fast. The restaurant is at "},{"type":"span","value":"Lækjargata 4","marks":["strong"]},{"type":"span","value":", close to the City Hall, Alþingi, and the bottom of Laugavegur."}]}]}},"blocks":{"img_frikadeller":{"_type":"image_block","image":"aizi9qhzmy","caption":"Smoked salmon with scrambled eggs, and roast beef smørrebrød."},"img_akaviti":{"_type":"image_block","image":"xd8fcqtfm3","caption":"The ákavíti fridge. They take their schnapps seriously."},"img_drinks":{"_type":"image_block","image":"e81xdey4dz","caption":"Tuborg Classic and schnapps glasses. The proper way to wash down smørrebrød."},"img_christmas":{"_type":"image_block","image":"5uqq7vitni","caption":"The full Christmas spread — mixed smørrebrød platter, beer, and schnapps. This is what December looks like at Jómfrúin."}}}}','2026-03-23T16:50:35.764Z','2026-03-24T16:57:47.826Z','Sunna','Sunna','Sunna',NULL,NULL,'Jómfrúin: The Maiden of Lækjargata','jomfruin','How an Icelandic man trained under Copenhagen''s smørrebrød royalty and brought the craft to Reykjavík — where it''s been a Saturday afternoon institution for nearly thirty years.','2026-03-23','1zb4ixb1xa','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Every Saturday afternoon from June through August, a back garden on Lækjargata fills with the sound of live jazz. People sit in the sun with plates of open-faced sandwiches and cold Icelandic beer. This is Jómfrúin — and it''s been doing this since 1996."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"From Copenhagen to Lækjargata"}]},{"type":"paragraph","children":[{"type":"span","value":"The story starts in 1888, at Oscar Davidsen''s legendary smørrebrød restaurant in Copenhagen — a place so famous its menu was once listed in the Guinness Book of Records as the longest in the world. Generations later, Ida Davidsen inherited the restaurant and continued the tradition."}]},{"type":"paragraph","children":[{"type":"span","value":"In the early 1990s, an Icelandic restaurateur named Jakob Jakobsson trained under Ida Davidsen — becoming the first man in the world to graduate as a "},{"type":"span","value":"smørrebrødsjomfru","marks":["emphasis"]},{"type":"span","value":", the traditional title for a master of open-faced sandwich preparation. The word translates roughly to \"smørrebrød maiden,\" and it had always been held by women. Jakob broke the mould."}]},{"type":"paragraph","children":[{"type":"span","value":"He brought the craft back to Reykjavík and opened Jómfrúin — \"The Maiden\" — on Lækjargata in 1996. The restaurant sits right in the heart of downtown, a few steps from the parliament building and Tjörnin pond."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"What you''re eating"}]},{"type":"paragraph","children":[{"type":"span","value":"Smørrebrød is deceptively simple: a single slice of dark rye bread, buttered, and then piled with toppings arranged with care. At Jómfrúin the classics are all here — pickled herring with onion, smoked salmon with capers, roast beef with remoulade and crispy onions, and the famous "},{"type":"span","value":"rækjupíramídi","marks":["emphasis"]},{"type":"span","value":" (shrimp pyramid!): a towering pyramid of shrimp on a sliver of bread that has become one of the most photographed dishes in Reykjavík."}]},{"type":"block","item":"img_frikadeller"},{"type":"paragraph","children":[{"type":"span","value":"The sandwiches are priced whole or half — and that''s the key to eating here well. You don''t commit to one enormous sandwich. You pick two halves, mix and match, and build your own lunch. The menu of the day always has pairing suggestions if you''re short on ideas, but here are ours: HC Andersen, Danish Adventure, Roast Beef Modern, Smoked Salmon, and Shrimp & Egg. Two halves, one plate, no regrets."}]},{"type":"paragraph","children":[{"type":"span","value":"Beyond the sandwiches, the warm dishes hold their own. "},{"type":"span","value":"Biksemad","marks":["emphasis"]},{"type":"span","value":" — a hash of diced meat and potatoes topped with a fried egg and pickled beets — is comfort food of the highest order."}]},{"type":"paragraph","children":[{"type":"span","value":"The Reykjavík Grapevine''s 2015 Best of Reykjavík panel described the "},{"type":"span","value":"rækjupíramídi","marks":["emphasis"]},{"type":"span","value":" as an \"honest-to-god pyramid of shrimp,\" and called out the \"Hangover\" — roast beef on rye with tomatoes, horseradish, and a fried egg — as a must-order."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"Ákavíti if you''re feeling cheeky"}]},{"type":"block","item":"img_akaviti"},{"type":"paragraph","children":[{"type":"span","value":"The fridge behind the bar is stocked with schnapps — ákavíti in Icelandic — and if you''re having the herring or the shrimp, a small cold glass alongside pairs nicely. It''s a tradition borrowed directly from Denmark, and Jómfrúin takes it seriously."}]},{"type":"block","item":"img_drinks"},{"type":"heading","level":2,"children":[{"type":"span","value":"The Saturday jazz"}]},{"type":"paragraph","children":[{"type":"span","value":"Since its opening year, Jómfrúin has hosted live jazz every Saturday afternoon in summer. Sigurður Flosason, one of Iceland''s most respected jazz musicians, curates the programme. The concerts run from 3 PM to 5 PM, admission is free, and they take place on Jómfrúartorg — the small square behind the restaurant. Check "},{"type":"link","url":"https://jomfruin.is/summar-jazz/","children":[{"type":"span","value":"jomfruin.is/summar-jazz"}]},{"type":"span","value":" for the schedule."}]},{"type":"paragraph","children":[{"type":"span","value":"What started as a casual summer tradition has become one of Reykjavík''s most beloved cultural rituals. The series has grown so popular it won the Icelandic Music Awards for Best Event. Arrive early if you want a seat — by 3 PM on a sunny Saturday, the garden is packed."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"Christmas at Jómfrúin"}]},{"type":"block","item":"img_christmas"},{"type":"paragraph","children":[{"type":"span","value":"Christmas is when Jómfrúin transforms. Families — sometimes groups of twenty or more — book the long tables months in advance. The platters come out piled high: mixed smørrebrød, warm dishes, beer, and schnapps. It has become a Reykjavík tradition for many families to gather here in December, and the restaurant books up fast. If you''re planning a Christmas lunch, call early."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"Still a family affair"}]},{"type":"paragraph","children":[{"type":"span","value":"Jakob''s son, Jakob Jr., took over as manager in 2015, having worked alongside his father since 2003. The handover was seamless — the same recipes, the same standards, the same unhurried pace. Walking into Jómfrúin today feels, as the Grapevine once put it, like being \"transported to 1985 Reykjavík.\" The wood-panelled interior hasn''t changed much. Neither has the quality."}]},{"type":"paragraph","children":[{"type":"span","value":"In a city where restaurants open and close with the seasons, Jómfrúin has been a constant for nearly thirty years. It''s the kind of place where the staff know the regulars, where the portions haven''t shrunk, and where nobody''s trying to reinvent anything. The smørrebrød is the same as it was when Jakob Sr. first laid rye bread on a board here — and that''s exactly the point."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The details"}]},{"type":"paragraph","children":[{"type":"span","value":"Jómfrúin is open daily for lunch and dinner. Reservations aren''t strictly necessary for weekday lunch, but weekend afternoons — especially during jazz season — fill up fast. The restaurant is at "},{"type":"span","value":"Lækjargata 4","marks":["strong"]},{"type":"span","value":", close to the City Hall, Alþingi, and the bottom of Laugavegur."}]}]}}');
